import re,os,glob
def slug(h):
    h=h.lower(); h=re.sub(r'[^a-z0-9 \-_]','',h); return h.replace(' ','-')
def heads(path):
    return {slug(re.sub(r'^#+\s*','',l).rstrip()) for l in open(path) if l.startswith('#')}
bad=[]
for f in ['AGENTS.md','custom.md','README.md','notes/README.md','TODO.md']+glob.glob('agent-data/*.md'):
    s=open(f).read(); d=os.path.dirname(f)
    defs=dict(re.findall(r'^\[([^\]]+)\]: (\S+)$', s, re.M))
    links=re.findall(r'\]\(([^)\s]+)\)', s)+list(defs.values())
    for l in links:
        if l.startswith('http') or l.startswith('mailto'): continue
        t,_,a=l.partition('#')
        tf=os.path.normpath(os.path.join(d,t)) if t else f
        if t.startswith('/'): tf=t.lstrip('/')
        if not os.path.exists(tf): bad.append((f,'nofile',l)); continue
        if a and tf.endswith('.md') and a not in heads(tf): bad.append((f,'noanchor',l))
for b in bad: print(b)
print('checked')
PY
